module hanabi_min_hints (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire input_valid,\n    input wire [7:0] input_card,\n    input wire [4:0] n_in,\n    output reg done,\n    output reg [3:0] answer\n);\n\n    // State declarations\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] READ = 4'd1;\n    localparam [3:0] INIT_MASK = 4'd2;\n    localparam [3:0] CHECK_MASK = 4'd3;\n    localparam [3:0] NEXT_MASK = 4'd4;\n    localparam [3:0] DONE = 4'd5;\n    reg [3:0] state;\n\n    // Internal registers\n    reg [3:0] card_count;\n    reg [9:0] mask;\n    reg [3:0] min_hints;\n    reg [3:0] i_reg, j_reg;\n    reg match_found;\n    reg [9:0] distinct_cards [0:15];  // Holds {color[3:0], value[3:0]} for 16 cards\n    reg [9:0] temp_signature_i, temp_signature_j;\n    reg [3:0] mask_popcount;\n    integer k;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            answer <= 4'd0;\n            card_count <= 4'd0;\n            min_hints <= 4'd10;\n            mask <= 10'd0;\n            i_reg <= 4'd0;\n            j_reg <= 4'd0;\n            match_found <= 1'b0;\n            for (k = 0; k < 16; k = k + 1) begin\n                distinct_cards[k] <= 10'd0;\n            end\n        end\n        else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= READ;\n                        card_count <= 4'd0;\n                    end\n                end\n\n                READ: begin\n                    if (input_valid) begin\n                        distinct_cards[card_count] <= {input_card[3:0], input_card[7:4]};\n                        if (card_count == (n_in - 5'd1)) begin\n                            state <= INIT_MASK;\n                        end\n                        else begin\n                            card_count <= card_count + 4'd1;\n                        end\n                    end\n                end\n\n                INIT_MASK: begin\n                    mask <= 10'd1;\n                    min_hints <= 4'd10;\n                    state <= CHECK_MASK;\n                    i_reg <= 4'd0;\n                    j_reg <= 4'd1;\n                    match_found <= 1'b0;\n                end\n\n                CHECK_MASK: begin\n                    // Compute mask_popcount\n                    mask_popcount <= mask[0] + mask[1] + mask[2] + mask[3] + mask[4] + \n                                     mask[5] + mask[6] + mask[7] + mask[8] + mask[9];\n\n                    // Compute current signatures\n                    temp_signature_i <= distinct_cards[i_reg] & mask;\n                    temp_signature_j <= distinct_cards[j_reg] & mask;\n\n                    // Signature comparison\n                    if (temp_signature_i == temp_signature_j) begin\n                        match_found <= 1'b1;\n                    end\n\n                    // Pair iteration control\n                    if (j_reg < (n_in - 5'd1)) begin\n                        j_reg <= j_reg + 4'd1;\n                    end\n                    else begin\n                        if (i_reg < (n_in - 5'd2)) begin\n                            i_reg <= i_reg + 4'd1;\n                            j_reg <= i_reg + 4'd2;\n                        end\n                        else begin\n                            // All pairs compared\n                            if (!match_found) begin\n                                if (mask_popcount < min_hints) begin\n                                    min_hints <= mask_popcount;\n                                end\n                            end\n                            state <= NEXT_MASK;\n                        end\n                    end\n                end\n\n                NEXT_MASK: begin\n                    if (mask == 10'd1023) begin\n                        state <= DONE;\n                        answer <= min_hints;\n                    end\n                    else begin\n                        mask <= mask + 10'd1;\n                        state <= CHECK_MASK;\n                        i_reg <= 4'd0;\n                        j_reg <= 4'd1;\n                        match_found <= 1'b0;\n                    end\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule